INSERT IGNORE INTO message (id, content, issuer, chat_id, create_date, update_date, delete_date) VALUES
(1, 'Boa tarde, minha internet está muito lenta desde ontem à noite.', 'USER', 1, '2026-06-06 08:10:00', '2026-06-06 08:10:00', NULL),
(2, 'Boa tarde! Sinto muito pelo transtorno. Pode me informar o número do seu contrato ou CPF para localizar sua conta?', 'AGENT', 1, '2026-06-06 08:20:00', '2026-06-06 08:20:00', NULL),
(3, 'Claro, meu CPF é o cadastrado na conta mesmo.', 'USER', 1, '2026-06-06 08:26:00', '2026-06-06 08:26:00', NULL),
(4, 'Perfeito, localizei aqui. Vou rodar um teste de sinal no seu modem, um instante.', 'AGENT', 1, '2026-06-06 08:39:00', '2026-06-06 08:39:00', NULL),
(5, 'Identifiquei uma oscilação na potência do sinal da sua região. Vou reiniciar remotamente o seu equipamento.', 'AGENT', 1, '2026-06-06 08:50:00', '2026-06-06 08:50:00', NULL),
(6, 'Ok, vou aguardar aqui.', 'USER', 1, '2026-06-06 08:58:00', '2026-06-06 08:58:00', NULL),
(7, 'Reiniciado! Pode verificar a velocidade agora, por favor?', 'AGENT', 1, '2026-06-06 09:09:00', '2026-06-06 09:09:00', NULL),
(8, 'Melhorou bastante, obrigado!', 'USER', 1, '2026-06-06 09:17:00', '2026-06-06 09:17:00', NULL),
(9, 'Alguns canais da minha TV a cabo estão fora do ar desde hoje cedo.', 'USER', 2, '2026-02-02 09:04:00', '2026-02-02 09:04:00', NULL),
(10, 'Bom dia! Vou verificar se há algum problema técnico na sua região.', 'AGENT', 2, '2026-02-02 09:14:00', '2026-02-02 09:14:00', NULL),
(11, 'Consta uma manutenção programada na central de sinal até às 18h de hoje.', 'AGENT', 2, '2026-02-02 09:23:00', '2026-02-02 09:23:00', NULL),
(12, 'Ah entendi, não sabia dessa manutenção.', 'USER', 2, '2026-02-02 09:26:00', '2026-02-02 09:26:00', NULL),
(13, 'Peço desculpas pela falta de aviso prévio, vou registrar sua reclamação.', 'AGENT', 2, '2026-02-02 09:40:00', '2026-02-02 09:40:00', NULL),
(14, 'Tudo bem, só queria confirmar se não era problema no meu decodificador.', 'USER', 2, '2026-02-02 09:42:00', '2026-02-02 09:42:00', NULL),
(15, 'Não, o equipamento está normal, o problema é da central mesmo.', 'AGENT', 2, '2026-02-02 09:57:00', '2026-02-02 09:57:00', NULL),
(16, 'Entendido, vou aguardar então.', 'USER', 2, '2026-02-02 10:00:00', '2026-02-02 10:00:00', NULL),
(17, 'Qualquer novidade te aviso por SMS. Obrigado pela paciência!', 'AGENT', 2, '2026-02-02 10:04:00', '2026-02-02 10:04:00', NULL),
(18, 'Só mais uma dúvida, isso pode acontecer novamente?', 'USER', 2, '2026-02-02 10:16:00', '2026-02-02 10:16:00', NULL),
